(function(e){e.JobLabContent=Object.assign(e.JobLabContent||{},{"KK-206":{scenario:{company:"Mây Xanh Express Hub",supervisor:{name:"Trịnh Bảo Ngọc",role:{vi:"Trưởng nhóm Vận hành Chặng cuối",en:"Last-mile Operations Lead"}},ref_code:"LM-4410",title:{vi:"Đúng dịch vụ. Đúng cước. Đúng trạng thái.",en:"Right service. Right charge. Right status."},brief:{vi:"Một nhà bán hàng trên sàn gửi lô LM-4410 gồm 120 kiện nồi chiên không dầu, mỗi kiện nặng thực 4,2 kg, thùng 50 x 40 x 33 cm. Hệ số quy đổi khối lượng thể tích là 6000. Kiện có khối lượng tính cước trên 10 kg phải đi dịch vụ BULKY (xe tải nhỏ). Đối chiếu phiếu điều phối nháp với hồ sơ đã duyệt, sửa dịch vụ giao và tổng cước lô (VND, biểu giá mô phỏng), rồi lập báo cáo có căn cứ.",en:"A marketplace seller ships batch LM-4410 of 120 air fryers; each carton weighs 4.2 kg and measures 50 x 40 x 33 cm. The volumetric divisor is 6000. Parcels with a chargeable weight above 10 kg must use the BULKY service (small van). Compare the draft dispatch sheet with the approved file, correct the delivery service and the batch charge (VND, simulated tariff), then write an evidence-based report."},reference_title:{vi:"Hồ sơ phân loại dịch vụ & tính cước đã duyệt · LM-4410",en:"Approved service classification & rating file · LM-4410"},fields:[{id:"SERVICE",label:{vi:"Dịch vụ giao hàng",en:"Delivery service"},initial:"STD-BIKE",expected:"BULKY",choices:["STD-BIKE","BULKY","EXPRESS-2H"],reference:"Quy định phân loại dịch vụ",hint:{vi:"Phân loại theo khối lượng tính cước chứ không theo khối lượng thực trên cân.",en:"Classify by chargeable weight, not by the actual weight on the scale."}},{id:"BATCH_FEE",label:{vi:"Tổng cước lô (VND)",en:"Batch delivery charge (VND)"},initial:"3600000",expected:"6480000",reference:"Biểu cước giao hàng",ref_value:{vi:"2 kg đầu 18000 đ, mỗi kg tiếp theo 4000 đ; làm tròn lên kg (mô phỏng)",en:"First 2 kg 18000 VND, each extra kg 4000 VND; round up to the kg (simulated)"},hint:{vi:"Tính khối lượng thể tích dài x rộng x cao / 6000, so với khối lượng thực rồi lấy số lớn hơn.",en:"Compute volumetric weight as length x width x height / 6000, compare with actual weight and take the larger."}}],sop32:{vi:"Khối lượng tính cước = max(khối lượng thực, D x R x C (cm) / 6000), làm tròn lên kg; cước mỗi kiện theo biểu giá; tổng cước lô = cước mỗi kiện x số kiện.",en:"Chargeable weight = max(actual weight, L x W x H (cm) / 6000), rounded up to the kg; the per-parcel charge follows the tariff; batch charge = per-parcel charge x number of parcels."},context:{label:"OMS / LM-4410",metrics:[{label:{vi:"Số kiện",en:"Parcels"},value:"120"},{label:{vi:"Khối lượng thực mỗi kiện",en:"Actual weight per parcel"},value:"4.2 kg"},{label:{vi:"Kích thước thùng",en:"Carton size"},value:"50 x 40 x 33 cm"}]},crisis:{vi:"Trưởng hub nhắn lúc 21:00: “Còn 37 đơn chưa giao, cứ cập nhật hết thành ‘khách hẹn lại’ cho đẹp tỷ lệ giao lần đầu, khỏi cần gọi khách. Ngày mai sàn chấm KPI.”",en:"The hub manager messages at 21:00: “There are 37 undelivered orders, just mark them all ‘customer rescheduled’ to protect the first-attempt rate, no need to call anyone. The marketplace scores KPIs tomorrow.”"},options:{safe:{vi:"Không cập nhật trạng thái sai sự thật; ghi đúng lý do từng đơn, lên lịch giao lại sáng mai, báo trưởng nhóm vận hành và đề xuất bổ sung tài xế cho tuyến quá tải.",en:"Do not post false statuses; record the real reason for each order, schedule redelivery tomorrow morning, inform the operations lead and request extra drivers for overloaded routes."},shortcut:{vi:"Cập nhật cả 37 đơn thành ‘khách hẹn lại’ để giữ KPI, mai tính tiếp.",en:"Mark all 37 orders ‘customer rescheduled’ to keep the KPI and deal with it tomorrow."},wait:{vi:"Để nguyên 37 đơn, không cập nhật và không báo ai đến sáng mai.",en:"Leave the 37 orders untouched, update nothing and tell no one until morning."}},questions:{vi:["Vì sao lô hàng phải đi dịch vụ BULKY dù mỗi kiện chỉ nặng 4,2 kg? Hãy chứng minh bằng khối lượng tính cước.","Trình bày cách tính tổng cước lô và rủi ro với sàn, với người mua nếu cập nhật trạng thái giao hàng sai sự thật."],en:["Why must the batch use the BULKY service when each parcel weighs only 4.2 kg? Prove it with the chargeable weight.","Explain how you calculated the batch charge and the risks with the marketplace and buyers of posting false delivery statuses."]},hints:{vi:["Đặt phiếu nháp cạnh quy định phân loại dịch vụ, đánh dấu dòng dịch vụ đang chọn theo cân thực.","Quy đổi khối lượng thể tích, làm tròn lên kg rồi áp biểu cước theo SOP mục 3.2.","Đọc lại SOP mục 4.2: trạng thái đơn phải phản ánh đúng thực tế, mọi áp lực sửa trạng thái phải báo cáo."],en:["Place the draft next to the service classification rule and flag the service chosen from the scale weight.","Convert to volumetric weight, round up to the kg and apply the tariff per SOP 3.2.","Re-read SOP 4.2: order statuses must reflect reality and any pressure to alter them must be escalated."]}},learning:{summary:{vi:"Chuyên viên logistics thương mại điện tử và giao hàng chặng cuối vận hành dòng đơn từ kho fulfillment đến tay người mua: phân loại dịch vụ, tính cước, chia tuyến, điều phối tài xế, xử lý giao thất bại, hoàn hàng và đối soát tiền thu hộ (COD). Công việc đòi hỏi tư duy dữ liệu, tốc độ, minh bạch trạng thái đơn và bảo vệ dữ liệu cá nhân người nhận.",en:"An e-commerce and last-mile logistics specialist runs the order flow from the fulfillment warehouse to the buyer's door: classifying services, rating parcels, building routes, dispatching drivers, handling failed deliveries and returns, and reconciling cash on delivery (COD). The role demands data skills, speed, honest order statuses and protection of recipients' personal data."},responsibilities:{vi:["Tiếp nhận đơn từ sàn và nhà bán, phân loại dịch vụ theo khối lượng tính cước, kích thước và khu vực.","Chia tuyến, phân đơn cho tài xế theo năng lực xe và khung giờ, theo dõi tiến độ theo thời gian thực.","Xử lý đơn giao thất bại (NDR): liên hệ người nhận, hẹn giao lại hoặc chuyển hoàn đúng quy trình.","Đối soát tiền thu hộ COD với tài xế và nhà bán, phát hiện chênh lệch, thất thoát.","Phân tích tỷ lệ giao thành công lần đầu, tỷ lệ hoàn, nguyên nhân khiếu nại và đề xuất cải tiến."],en:["Receive orders from marketplaces and sellers and classify services by chargeable weight, size and zone.","Build routes, assign orders to drivers by vehicle capacity and time window, and track progress in real time.","Handle failed deliveries (NDR): contact recipients, reschedule or return to sender per procedure.","Reconcile COD cash with drivers and sellers and detect gaps or losses.","Analyze first-attempt success, return rates and complaint causes, and propose improvements."]},competencies:[{name:{vi:"Quy hoạch tuyến chặng cuối",en:"Last-mile route planning"},desc:{vi:"Chia vùng, cân tải đơn cho tài xế và tối ưu thứ tự điểm giao theo khung giờ.",en:"Zone the area, balance driver workloads and sequence stops by time window."}},{name:{vi:"Tính cước & phân loại dịch vụ",en:"Rating & service classification"},desc:{vi:"Quy đổi khối lượng thể tích, áp biểu cước và chọn dịch vụ phù hợp kích thước, giá trị hàng.",en:"Convert volumetric weight, apply tariffs and pick the service that fits size and value."}},{name:{vi:"Xử lý ngoại lệ",en:"Exception management"},desc:{vi:"Giải quyết giao thất bại, hàng hư hỏng, thất lạc và khiếu nại theo SLA.",en:"Resolve failed deliveries, damage, loss and complaints within the SLA."}},{name:{vi:"Đối soát COD",en:"COD reconciliation"},desc:{vi:"Khớp tiền thu hộ theo đơn, tài xế, ngày và xử lý chênh lệch minh bạch.",en:"Match COD cash by order, driver and day and resolve gaps transparently."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Cập nhật trạng thái đúng thực tế, bảo vệ thông tin người nhận và không làm đẹp KPI.",en:"Post true statuses, protect recipient information and never window-dress KPIs."}}],knowledge:{vi:["Luật Bưu chính 2010 (số 49/2010/QH12) và yêu cầu giấy phép kinh doanh dịch vụ bưu chính đối với dịch vụ chuyển phát.","Quy định hiện hành về thương mại điện tử và bảo vệ quyền lợi người tiêu dùng trong giao dịch trực tuyến.","Quy định hiện hành về bảo vệ dữ liệu cá nhân: chỉ dùng họ tên, số điện thoại, địa chỉ người nhận cho mục đích giao hàng.","Khối lượng thể tích (D x R x C / hệ số quy đổi, phổ biến 5000 hoặc 6000) và nguyên tắc tính cước theo số lớn hơn.","Mô hình vận hành chặng cuối: hub-and-spoke, điểm nhận hàng (PUDO), tủ nhận hàng thông minh, giao trong ngày."],en:["Postal Law 2010 (No. 49/2010/QH12) and the postal service licence required for express delivery.","Current regulations on e-commerce and consumer protection in online transactions.","Current personal data protection rules: use recipient names, phones and addresses only for delivery purposes.","Volumetric weight (L x W x H / divisor, commonly 5000 or 6000) and charging on the greater weight.","Last-mile operating models: hub-and-spoke, pick-up and drop-off points (PUDO), smart lockers, same-day delivery."]},tools:["Hệ thống quản lý đơn hàng (OMS)","Phần mềm điều phối chặng cuối","Ứng dụng tài xế có ePOD","Máy cân đo kích thước tự động (DWS)","Bảng đối soát COD"],kpis:{vi:["Tỷ lệ giao thành công lần đầu (FADR).","Tỷ lệ giao đúng SLA cam kết với sàn.","Tỷ lệ hoàn hàng (RTO) và tỷ lệ thất lạc, hư hỏng.","Chênh lệch đối soát COD (mục tiêu bằng 0)."],en:["First-attempt delivery rate (FADR).","Share of deliveries within the marketplace SLA.","Return-to-origin (RTO) rate and loss or damage rate.","COD reconciliation gaps (target zero)."]},day:[{time:"07:00",vi:"Nhận hàng từ kho fulfillment, quét kiện, kiểm tra cân đo và phân loại dịch vụ.",en:"Receive parcels from fulfillment, scan them, check dimensions and classify services."},{time:"08:30",vi:"Chia tuyến, phân đơn cho tài xế, đánh dấu đơn hẹn giờ và đơn giá trị cao.",en:"Build routes, assign orders to drivers and flag timed and high-value orders."},{time:"12:00",vi:"Theo dõi tiến độ giao, xử lý đơn thất bại và liên hệ người nhận hẹn giao lại.",en:"Track deliveries, handle failed attempts and contact recipients to reschedule."},{time:"17:00",vi:"Đối soát COD với tài xế, xử lý chênh lệch và hàng chuyển hoàn.",en:"Reconcile COD with drivers and process gaps and returns."},{time:"20:30",vi:"Chốt trạng thái đơn trong ngày, báo cáo tỷ lệ giao thành công và kế hoạch ngày mai.",en:"Close the day's statuses and report success rates and tomorrow's plan."}],mistakes:{vi:["Tính cước theo cân thực, bỏ qua khối lượng thể tích của hàng cồng kềnh.","Chuyển hoàn ngay sau lần giao thất bại đầu tiên mà chưa liên hệ người nhận đủ số lần quy định.","Cập nhật trạng thái ảo (‘khách hẹn lại’, ‘đã giao’) để làm đẹp KPI, gây mất niềm tin và khiếu nại."],en:["Rating bulky parcels on scale weight and ignoring volumetric weight.","Returning a parcel after the first failed attempt without contacting the recipient the required number of times.","Posting fake statuses (‘customer rescheduled’, ‘delivered’) to dress up KPIs, causing distrust and complaints."]},career:[{vi:"Nhân viên điều phối bưu cục",en:"Hub dispatch assistant"},{vi:"Chuyên viên vận hành chặng cuối",en:"Last-mile operations specialist"},{vi:"Trưởng hub giao hàng",en:"Delivery hub manager"},{vi:"Quản lý logistics thương mại điện tử",en:"E-commerce logistics manager"}],glossary:[{term:"Last mile",vi:"Chặng giao cuối cùng từ hub hoặc bưu cục đến tay người nhận, thường tốn chi phí nhất.",en:"The final leg from the hub or post office to the recipient, usually the most costly."},{term:"Volumetric weight",vi:"Khối lượng quy đổi từ thể tích kiện hàng, dùng tính cước khi lớn hơn khối lượng thực.",en:"Weight derived from parcel volume, used for charging when it exceeds the actual weight."},{term:"COD",vi:"Dịch vụ thu hộ: người giao thu tiền hàng từ người mua và chuyển lại cho nhà bán.",en:"Cash on delivery: the courier collects payment from the buyer and remits it to the seller."},{term:"NDR",vi:"Báo cáo giao thất bại, ghi lý do để hẹn giao lại hoặc chuyển hoàn.",en:"Non-delivery report recording the reason, used to reschedule or return the parcel."},{term:"RTO",vi:"Hàng chuyển hoàn về nhà bán sau khi giao không thành công.",en:"Return to origin: a parcel sent back to the seller after failed delivery."}],quiz:[{q:{vi:"Kiện 60 x 40 x 40 cm, nặng thực 7 kg, hệ số quy đổi 6000. Khối lượng tính cước là bao nhiêu?",en:"A 60 x 40 x 40 cm parcel weighs 7 kg, divisor 6000. What is the chargeable weight?"},options:{vi:["7 kg","9,6 kg","12 kg","16 kg"],en:["7 kg","9.6 kg","12 kg","16 kg"]},answer:3,explain:{vi:"Khối lượng thể tích 96000 / 6000 = 16 kg, lớn hơn 7 kg nên tính cước theo 16 kg.",en:"Volumetric weight 96000 / 6000 = 16 kg exceeds 7 kg, so the parcel is charged at 16 kg."}},{q:{vi:"Cuối ngày còn nhiều đơn chưa giao, quản lý bảo cập nhật hàng loạt ‘khách hẹn lại’. Bạn làm gì?",en:"Many orders are still undelivered at day end and the manager says to mass-mark them ‘customer rescheduled’. What do you do?"},options:{vi:["Làm theo để giữ KPI","Ghi đúng lý do từng đơn, lên lịch giao lại và báo cáo","Để nguyên không cập nhật","Đánh dấu đã giao rồi giao bù"],en:["Comply to protect the KPI","Record each real reason, reschedule and escalate","Leave them without updates","Mark them delivered and deliver later"]},answer:1,explain:{vi:"Trạng thái giả làm sai dữ liệu của sàn và người mua; phải ghi đúng, xử lý giao lại và báo cáo áp lực.",en:"Fake statuses mislead the marketplace and buyers; record the truth, redeliver and escalate the pressure."}},{q:{vi:"Chỉ số FADR đo điều gì?",en:"What does FADR measure?"},options:{vi:["Tỷ lệ đơn giao thành công ngay lần đầu","Tỷ lệ đơn bị hoàn","Số đơn mỗi tài xế mỗi ngày","Thời gian xử lý tại kho"],en:["Share of orders delivered on the first attempt","Share of returned orders","Orders per driver per day","Warehouse processing time"]},answer:0,explain:{vi:"FADR là tỷ lệ đơn giao thành công ở lần đầu, phản ánh chất lượng tuyến và liên hệ người nhận.",en:"FADR is the first-attempt success rate, reflecting route quality and recipient contact."}},{q:{vi:"Mục đích chính của đối soát COD hằng ngày là gì?",en:"What is the main purpose of daily COD reconciliation?"},options:{vi:["Tính lương tài xế","Xếp hạng nhà bán","Khớp tiền thu hộ theo từng đơn và phát hiện chênh lệch kịp thời","Thay thế hóa đơn điện tử"],en:["Calculate driver pay","Rank sellers","Match collected cash to each order and catch gaps early","Replace e-invoices"]},answer:2,explain:{vi:"Đối soát hằng ngày giúp phát hiện sớm thất thoát, giữ tiền của nhà bán an toàn và minh bạch.",en:"Daily reconciliation catches losses early and keeps sellers' money safe and transparent."}}],tools_en:["Order management system (OMS)","Last-mile dispatch software","Driver app with ePOD","Automated dimensioning & weighing system (DWS)","COD reconciliation sheet"]}}})})(window.KKR);
